```python
def _make_getset_interval(method_name, lim_name, attr_name):
    """
    Helper to generate ``get_{data,view}_interval`` and
    ``set_{data,view}_interval`` implementations.
    """

    def getter(self):
        # docstring inherited.
        return getattr(getattr(self.axes, lim_name), attr_name)

    def setter(self, vmin, vmax, ignore=False):
        # docstring inherited.
        if ignore:
            setattr(getattr(self.axes, lim_name), attr_name, (vmin, vmax))
        else:
            oldmin, oldmax = getter(self)
            if oldmin < oldmax:
                setter(self, min(vmin, vmax, oldmin), max(vmin, vmax, oldmax),
                       ignore=True)
            else:
                setter(self, max(vmin, vmax, oldmax), min(vmin, vmax, oldmin),
                       ignore=True)
        self.stale = True

    # This needs to handle both x and y intervals properly
    if attr_name == 'intervalx':
        getter.__name__ = f"get_{method_name}_x_interval"
        setter.__name__ = f"set_{method_name}_x_interval"
    else:
        getter.__name__ = f"get_{method_name}_y_interval"
        setter.__name__ = f"set_{method_name}_y_interval"

    return getter, setter
```

